pub mod error;
pub mod handlers;
pub mod state;

pub use error::{CommandError, CommandResult};
// Glob re-export so that the helper symbols generated by `#[tauri::command]`
// (named `__cmd__<fn>` and `__tauri_command_name_<fn>`) are visible at
// `crate::commands::<fn>`, where `tauri::generate_handler!` looks for them.
pub use handlers::*;
pub use state::AppState;

#[cfg(test)]
mod tests {
    use super::*;
    use crate::db::DbError;
    use crate::roots::RootError;

    #[test]
    fn command_error_serializes_with_code_and_message() {
        let err = CommandError::new("not_found", "root id 5");
        let json = serde_json::to_string(&err).unwrap();
        assert!(json.contains("\"code\":\"not_found\""));
        assert!(json.contains("\"message\":\"root id 5\""));
    }

    #[test]
    fn db_not_found_maps_to_not_found_code() {
        let e: CommandError = DbError::NotFound("x".into()).into();
        assert_eq!(e.code, "not_found");
    }

    #[test]
    fn root_invalid_kind_maps_to_invalid_kind_code() {
        let e: CommandError = RootError::InvalidKind("cloud".into()).into();
        assert_eq!(e.code, "invalid_kind");
        assert!(e.message.contains("cloud"));
    }

    #[test]
    fn root_db_not_found_maps_through_to_not_found() {
        let e: CommandError = RootError::Db(DbError::NotFound("y".into())).into();
        assert_eq!(e.code, "not_found");
    }

    #[test]
    fn io_error_maps_to_io_code() {
        let e: CommandError = std::io::Error::new(std::io::ErrorKind::NotFound, "boom").into();
        assert_eq!(e.code, "io");
        assert!(e.message.contains("boom"));
    }
}
